// Generated by deviceloop flow export from flow "fixture-fail".

import XCTest

final class FixtureFailFlowTests: XCTestCase {
    @MainActor
    func testFixtureFail() throws {
        continueAfterFailure = false
        addTeardownBlock { @MainActor in
            self.continueAfterFailure = true
            XCTContext.runActivity(named: "cleanup[0] press") { _ in
                XCUIDevice.shared.press(.home)
            }
        }
        let app = XCUIApplication(bundleIdentifier: "com.argmaxinc.deviceloop.exportcheck")
        app.launchArguments = ["--deviceloop-fixture"]
        app.launchEnvironment = [:]
        app.launch()

        XCTContext.runActivity(named: "steps[0] assert") { _ in
            let element = uniqueElement(app.descendants(matching: .any).matching(identifier: "fixture.counter.value"), timeout: 30)
            _ = element.wait(for: \.label, toEqual: "Count: 0", timeout: 30)
            XCTAssertEqual(element.label, "Count: 0")
        }
        XCTContext.runActivity(named: "steps[1] tap") { _ in
            uniqueElement(app.descendants(matching: .any).matching(identifier: "fixture.counter.increment"), timeout: 30).tap()
        }
        XCTContext.runActivity(named: "steps[2] assert") { _ in
            let element = uniqueElement(app.descendants(matching: .any).matching(identifier: "fixture.counter.value"), timeout: 3)
            _ = element.wait(for: \.label, toEqual: "Count: 2", timeout: 3)
            XCTAssertEqual(element.label, "Count: 2")
        }
        XCTContext.runActivity(named: "steps[3] tap") { _ in
            uniqueElement(app.descendants(matching: .any).matching(identifier: "fixture.counter.increment"), timeout: 30).tap()
        }
    }
}

/// The one element `query` matches, after waiting up to `timeout` seconds for exactly one match.
@MainActor
private func uniqueElement(_ query: XCUIElementQuery, timeout: TimeInterval, file: StaticString = #filePath, line: UInt = #line)
    -> XCUIElement
{
    let deadline = Date().addingTimeInterval(timeout)
    XCTAssertTrue(query.firstMatch.waitForExistence(timeout: timeout), "No element matches the query.", file: file, line: line)
    while query.count != 1, Date() < deadline { RunLoop.current.run(until: Date().addingTimeInterval(0.2)) }
    XCTAssertEqual(query.count, 1, "The query must match one element.", file: file, line: line)
    return query.element
}
